export interface LessonPlan {
  discipline: string;
  content: string;
  context: string;
  learningObjectives: string[];
  methodology: string;
  development: {
    what: string;
    how: string;
  };
  learningEvidence: string[];
  assessmentInstruments: string[];
}

export interface AppState {
  isGenerating: boolean;
  plan: LessonPlan | null;
  error: string | null;
}

import { GoogleGenAI, Type } from "@google/genai";
import { LessonPlan } from "../types";

const SYSTEM_INSTRUCTION = `Você é um assistente pedagógico institucional.
Seu papel é ORGANIZAR, SISTEMATIZAR e QUALIFICAR a ideia do professor, sem substituir, apagar ou enfraquecer sua autoria intelectual.

REGRAS:
1. Identifique implicitamente: disciplina, conteúdo, objetivos de aprendizagem e contexto.
2. Organize seguindo RIGOROSAMENTE o padrão SESI/BNCC.
3. Use a Taxonomia de Bloom para os objetivos (lembrar, compreender, aplicar, analisar, avaliar, criar).
4. O plano deve conter: Metodologia, Desenvolvimento (O que/Como), Evidências de aprendizagem e Instrumentos de avaliação.
5. Priorize metodologias ativas e inclusivas.
6. A avaliação deve ser formativa.
7. Retorne o resultado EXCLUSIVAMENTE em formato JSON.

O professor é o autor. Você é a ferramenta de mediação.`;

const lessonPlanSchema = {
  type: Type.OBJECT,
  properties: {
    discipline: { type: Type.STRING, description: "Disciplina ou área do conhecimento" },
    content: { type: Type.STRING, description: "Conteúdo principal da aula" },
    context: { type: Type.STRING, description: "Breve contexto pedagógico da proposta" },
    learningObjectives: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Objetivos de aprendizagem baseados na Taxonomia de Bloom"
    },
    methodology: { type: Type.STRING, description: "Metodologia de ensino proposta" },
    development: {
      type: Type.OBJECT,
      properties: {
        what: { type: Type.STRING, description: "O que será feito em aula?" },
        how: { type: Type.STRING, description: "Como será feito em aula?" }
      },
      required: ["what", "how"]
    },
    learningEvidence: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Evidências de aprendizagem esperadas"
    },
    assessmentInstruments: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Instrumentos de avaliação formativa"
    }
  },
  required: ["discipline", "content", "learningObjectives", "methodology", "development", "learningEvidence", "assessmentInstruments"]
};

export async function generateLessonPlan(teacherText: string): Promise<LessonPlan> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Transforme este texto livre do professor em um plano de aula estruturado SESI/BNCC: "${teacherText}"`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: lessonPlanSchema,
        temperature: 0.7,
      },
    });

    const result = JSON.parse(response.text || "{}");
    return result as LessonPlan;
  } catch (error) {
    console.error("Erro ao gerar plano:", error);
    throw new Error("Não foi possível processar a proposta pedagógica. Verifique sua conexão ou tente novamente.");
  }
}

import React, { useState, useCallback } from 'react';
import { generateLessonPlan } from './services/geminiService';
import { LessonPlan, AppState } from './types';
import Header from './components/Header';
import Footer from './components/Footer';
import PlanResult from './components/PlanResult';
import { BookOpen, Send, Loader2, Info } from 'lucide-react';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [state, setState] = useState<AppState>({
    isGenerating: false,
    plan: null,
    error: null,
  });

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    setState(prev => ({ ...prev, isGenerating: true, error: null }));

    try {
      const generatedPlan = await generateLessonPlan(inputText);
      setState({
        isGenerating: false,
        plan: generatedPlan,
        error: null
      });
    } catch (err: any) {
      setState(prev => ({
        ...prev,
        isGenerating: false,
        error: err.message || "Ocorreu um erro inesperado."
      }));
    }
  }, [inputText]);

  const handleReset = () => {
    setState({ isGenerating: false, plan: null, error: null });
    setInputText('');
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-8 max-w-5xl">
        {!state.plan ? (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 md:p-8">
              <div className="flex items-start space-x-4 mb-6">
                <div className="bg-blue-100 p-3 rounded-xl">
                  <BookOpen className="text-blue-600 w-6 h-6" />
                </div>
                <div>
                  <h2 className="text-xl font-semibold text-slate-800">Nova Proposta Pedagógica</h2>
                  <p className="text-slate-500 mt-1">
                    Descreva livremente sua ideia para a aula. Identificaremos objetivos, 
                    metodologias e instrumentos de avaliação seguindo o padrão SESI/BNCC.
                  </p>
                </div>
              </div>

              <form onSubmit={handleSubmit} className="space-y-4">
                <textarea
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  placeholder="Ex: Gostaria de uma aula de história sobre a Revolução Industrial para o 8º ano, focando no impacto nas cidades e usando uma atividade prática de mapa mental..."
                  className="w-full h-48 p-4 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none resize-none text-slate-700 leading-relaxed"
                  disabled={state.isGenerating}
                />

                <div className="flex items-center justify-between">
                  <div className="flex items-center text-xs text-slate-400">
                    <Info className="w-4 h-4 mr-1" />
                    Sua autoria intelectual será integralmente preservada.
                  </div>
                  <button
                    type="submit"
                    disabled={state.isGenerating || !inputText.trim()}
                    className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 text-white px-6 py-3 rounded-xl font-medium transition-all shadow-md active:scale-95"
                  >
                    {state.isGenerating ? (
                      <>
                        <Loader2 className="w-5 h-5 animate-spin" />
                        <span>Sistematizando...</span>
                      </>
                    ) : (
                      <>
                        <Send className="w-5 h-5" />
                        <span>Qualificar Plano</span>
                      </>
                    )}
                  </button>
                </div>
              </form>
            </div>

            {state.error && (
              <div className="bg-red-50 border border-red-100 text-red-600 p-4 rounded-xl flex items-center">
                <span className="font-medium">Ops!</span>
                <span className="ml-2">{state.error}</span>
              </div>
            )}

            <section className="grid md:grid-cols-3 gap-6">
              {[
                { title: 'Padrão Institucional', desc: 'Alinhamento imediato com as diretrizes SESI e BNCC.' },
                { title: 'Taxonomia de Bloom', desc: 'Objetivos estruturados para garantir progressão cognitiva.' },
                { title: 'Educação Inclusiva', desc: 'Metodologias focadas na diversidade e ritmos de aprendizagem.' }
              ].map((item, idx) => (
                <div key={idx} className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                  <h3 className="font-semibold text-slate-700 mb-2">{item.title}</h3>
                  <p className="text-sm text-slate-500 leading-relaxed">{item.desc}</p>
                </div>
              ))}
            </section>
          </div>
        ) : (
          <PlanResult plan={state.plan} onReset={handleReset} />
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;

