import React, { useState, useCallback, useEffect } from 'react';
import { generateLessonPlan } from './services/geminiService';
import { storageService } from './services/storageService';
import { LessonPlan, AppState, SavedLessonPlan } from './types';
import Header from './components/Header';
import Footer from './components/Footer';
import PlanResult from './components/PlanResult';
import HistoryDrawer from './components/HistoryDrawer';
import { BookOpen, Send, Loader2, Info } from 'lucide-react';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [state, setState] = useState<AppState>({
    isGenerating: false,
    plan: null,
    error: null,
    showHistory: false
  });
  const [history, setHistory] = useState<SavedLessonPlan[]>([]);

  // Carregar histórico inicial
  useEffect(() => {
    setHistory(storageService.getHistory());
  }, []);

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    setState(prev => ({ ...prev, isGenerating: true, error: null }));

    try {
      const generatedPlan = await generateLessonPlan(inputText);

      // Salva automaticamente no "Banco"
      storageService.savePlan(generatedPlan);
      // Atualiza lista local
      setHistory(storageService.getHistory());

      setState({
        isGenerating: false,
        plan: generatedPlan,
        error: null,
        showHistory: false
      });
    } catch (err: any) {
      setState(prev => ({
        ...prev,
        isGenerating: false,
        error: err.message || "Ocorreu um erro inesperado."
      }));
    }
  }, [inputText]);

  const handleReset = () => {
    setState({ isGenerating: false, plan: null, error: null, showHistory: false });
    setInputText('');
  };

  const handleSelectHistoryPlan = (savedPlan: SavedLessonPlan) => {
    setState(prev => ({
      ...prev,
      plan: savedPlan,
      showHistory: false, // Fecha o drawer ao selecionar
      error: null
    }));
  };

  const handleDeletePlan = (id: string) => {
    if (confirm('Tem certeza que deseja excluir este plano do histórico?')) {
      const updated = storageService.deletePlan(id);
      setHistory(updated);
    }
  };

  return (
    <div className="min-h-screen flex flex-col text-slate-100 relative">
      <Header onOpenHistory={() => setState(prev => ({ ...prev, showHistory: true }))} />

      <HistoryDrawer 
        isOpen={state.showHistory}
        onClose={() => setState(prev => ({ ...prev, showHistory: false }))}
        history={history}
        onSelectPlan={handleSelectHistoryPlan}
        onDeletePlan={handleDeletePlan}
      />

      <main className="flex-grow container mx-auto px-4 py-8 max-w-5xl">
        {!state.plan ? (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* Card Principal - Preto com detalhes Laranja */}
            <div className="bg-black rounded-2xl shadow-2xl border border-orange-500/20 p-6 md:p-8 relative overflow-hidden">
              <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600/10 rounded-full blur-3xl -mr-10 -mt-10 pointer-events-none"></div>

              <div className="flex items-start space-x-4 mb-6 relative z-10">
                <div className="bg-orange-500/10 p-3 rounded-xl border border-orange-500/20">
                  <BookOpen className="text-orange-500 w-6 h-6" />
                </div>
                <div>
                  <h2 className="text-xl font-semibold text-white">Nova Proposta Pedagógica</h2>
                  <p className="text-slate-400 mt-1">
                    Descreva livremente sua ideia para a aula. Seu plano será gerado, qualificado e 
                    <span className="text-orange-500 font-bold"> salvo automaticamente no seu banco de dados.</span>
                  </p>
                </div>
              </div>

              <form onSubmit={handleSubmit} className="space-y-4 relative z-10">
                <textarea
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  placeholder="Ex: Gostaria de uma aula de história sobre a Revolução Industrial para o 8º ano, focando no impacto nas cidades e usando uma atividade prática de mapa mental..."
                  className="w-full h-48 p-4 rounded-xl bg-slate-900 border border-slate-700 focus:ring-2 focus:ring-orange-500 focus:border-transparent transition-all outline-none resize-none text-slate-200 placeholder-slate-600 leading-relaxed"
                  disabled={state.isGenerating}
                />

                <div className="flex items-center justify-between">
                  <div className="flex items-center text-xs text-slate-500">
                    <Info className="w-4 h-4 mr-1 text-orange-500" />
                    Sua autoria intelectual será integralmente preservada.
                  </div>
                  <button
                    type="submit"
                    disabled={state.isGenerating || !inputText.trim()}
                    className="flex items-center space-x-2 bg-orange-600 hover:bg-orange-700 disabled:bg-slate-800 disabled:text-slate-500 text-white px-6 py-3 rounded-xl font-bold transition-all shadow-lg active:scale-95 border border-orange-500/50"
                  >
                    {state.isGenerating ? (
                      <>
                        <Loader2 className="w-5 h-5 animate-spin" />
                        <span>Sistematizando e Salvando...</span>
                      </>
                    ) : (
                      <>
                        <Send className="w-5 h-5" />
                        <span>Gerar e Salvar Plano</span>
                      </>
                    )}
                  </button>
                </div>
              </form>
            </div>

            {state.error && (
              <div className="bg-red-900/30 border border-red-500/30 text-red-400 p-4 rounded-xl flex items-center">
                <span className="font-medium">Ops!</span>
                <span className="ml-2">{state.error}</span>
              </div>
            )}

            <section className="grid md:grid-cols-3 gap-6">
              {[
                { title: 'Banco de Planos', desc: 'Todo plano gerado é salvo automaticamente no seu histórico.' },
                { title: 'Taxonomia de Bloom', desc: 'Objetivos estruturados para garantir progressão cognitiva.' },
                { title: 'Educação Inclusiva', desc: 'Metodologias focadas na diversidade e ritmos de aprendizagem.' }
              ].map((item, idx) => (
                <div key={idx} className="bg-black p-6 rounded-2xl border border-white/10 hover:border-orange-500/50 transition-colors group">
                  <h3 className="font-semibold text-slate-200 mb-2 group-hover:text-orange-400 transition-colors">{item.title}</h3>
                  <p className="text-sm text-slate-500 leading-relaxed">{item.desc}</p>
                </div>
              ))}
            </section>
          </div>
        ) : (
          <PlanResult plan={state.plan} onReset={handleReset} />
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { LessonPlan } from "../types";

const SYSTEM_INSTRUCTION = `Você é um Consultor Pedagógico de Elite, especializado em BNCC e metodologias ativas.
Sua missão não é apenas formatar, mas ELEVAR a qualidade da ideia do professor, tornando-a uma proposta de aula memorável, exequível e profundamente coerente.

O INIMIGO É O GENÉRICO.
Seu plano deve ser tão específico que um professor substituto poderia aplicá-lo apenas lendo seu texto.

REGRAS DE OURO (ANTI-GENÉRICO):
1.  **Especificidade Radical**: Nunca escreva "discutir sobre o tema" ou "fazer uma atividade prática".
    *   *Errado:* "Os alunos farão um debate."
    *   *Correto:* "Os alunos participarão de um debate guiado pela pergunta central: '[Inserir pergunta polêmica específica do conteúdo]'."
    *   *Errado:* "Atividade lúdica."
    *   *Correto:* "Criação de um jogo de tabuleiro onde as casas representam as etapas de [Processo específico do conteúdo]."

2.  **Coerência Pedagógica**:
    *   A metodologia escolhida deve ser a MELHOR para aquele conteúdo específico, não apenas uma escolha aleatória.
    *   O "Como fazer" deve realizar concretamente os Objetivos de Aprendizagem listados.

3.  **Variação Metodológica Inteligente**:
    *   Evite a zona de conforto. Intercale entre: Aprendizagem Baseada em Problemas (PBL), Sala de Aula Invertida, Rotação por Estações, Gamificação (com regras claras), Storytelling, Design Thinking ou Instrução por Pares.
    *   Se o conteúdo for denso, use metodologias de síntese criativa. Se for prático, use metodologias de "mão na massa".

ESTRUTURA DE RESPOSTA (JSON):
- **methodology**: Nome da metodologia ativa + Justificativa pedagógica curta de por que ela funciona para ESTE conteúdo.
- **development.what**: OBRIGATORIAMENTE um PARÁGRAFO ÚNICO, denso e técnico (entre 6 a 8 linhas). NÃO use tópicos. Narre a progressão da aula (início, meio e fim) de forma fluida, utilizando linguagem pedagógica formal para descrever a intencionalidade das ações e a sequência didática.
- **development.how**: O roteiro detalhado da dinâmica. Como o professor agrupa? O que ele entrega? O que o aluno produz?
- **learningObjectives**: Verbos da Taxonomia de Bloom (Do simples ao complexo).
- **learningEvidence**: O que o aluno entrega tangivelmente (um texto, um desenho, uma fala, um esquema)?

Tom de voz: Profissional, inspirador, direto e tecnicamente preciso (Padrão BNCC).`;

const lessonPlanSchema = {
  type: Type.OBJECT,
  properties: {
    discipline: { type: Type.STRING },
    content: { type: Type.STRING },
    context: { type: Type.STRING },
    learningObjectives: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    methodology: { type: Type.STRING, description: "Nome da metodologia ativa e justificativa específica para o tema" },
    development: {
      type: Type.OBJECT,
      properties: {
        what: { type: Type.STRING, description: "Parágrafo único, técnico e robusto (aprox. 6 linhas) narrando a sequência didática." },
        how: { type: Type.STRING, description: "Detalhamento da dinâmica (Como acontece, regras, agrupamentos)" }
      },
      required: ["what", "how"]
    },
    learningEvidence: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    assessmentInstruments: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    }
  },
  required: ["discipline", "content", "learningObjectives", "methodology", "development", "learningEvidence", "assessmentInstruments"]
};

export async function generateLessonPlan(teacherText: string): Promise<LessonPlan> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Professor solicitou: "${teacherText}".

      Gere um plano de aula que NÃO SEJA GENÉRICO.
      Se o professor deu poucos detalhes, INFERIRA um contexto rico e específico para tornar a aula aplicável.
      Conecte o conteúdo a situações reais ou problemas contemporâneos.`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: lessonPlanSchema,
        temperature: 0.7, // Reduzido levemente para focar mais na coerência e menos na "alucinação" criativa excessiva
      },
    });

    return JSON.parse(response.text || "{}") as LessonPlan;
  } catch (error) {
    console.error("Erro ao gerar plano:", error);
    throw new Error("Não foi possível processar a proposta pedagógica. Tente detalhar um pouco mais o tema.");
  }
}

