import { LessonPlan, SavedLessonPlan } from "../types";

const STORAGE_KEY = 'pedagogical_assistant_history';

// Função segura para gerar ID em qualquer ambiente
const generateId = (): string => {
  // Tenta usar a API nativa de criptografia se disponível e segura
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    try {
      return crypto.randomUUID();
    } catch (e) {
      console.warn("crypto.randomUUID falhou, usando fallback", e);
    }
  }
  // Fallback robusto: timestamp + random string
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 15);
};

export const storageService = {
  savePlan: (plan: LessonPlan): SavedLessonPlan => {
    const history = storageService.getHistory();

    const newSavedPlan: SavedLessonPlan = {
      ...plan,
      id: generateId(),
      createdAt: new Date().toISOString(),
    };

    // Adiciona no início da lista
    const updatedHistory = [newSavedPlan, ...history];

    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedHistory));
    } catch (e) {
      console.error("Erro ao salvar no localStorage (possivelmente quota excedida):", e);
      throw new Error("Não foi possível salvar o plano no histórico. Verifique o armazenamento do navegador.");
    }

    return newSavedPlan;
  },

  getHistory: (): SavedLessonPlan[] => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (!stored) return [];

      const parsed = JSON.parse(stored);
      // Validação básica para garantir que é um array
      if (!Array.isArray(parsed)) return [];

      return parsed;
    } catch (e) {
      console.error("Erro ao ler histórico", e);
      // Se houver erro de leitura, reseta para evitar travamento
      return [];
    }
  },

  deletePlan: (id: string): SavedLessonPlan[] => {
    const history = storageService.getHistory();
    const updatedHistory = history.filter(plan => plan.id !== id);
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedHistory));
    } catch (e) {
      console.error("Erro ao atualizar histórico após exclusão", e);
    }
    return updatedHistory;
  }
};

import { LessonPlan, SavedLessonPlan } from "../types";

const STORAGE_KEY = 'pedagogical_assistant_history';

// Gerador de ID simples e compatível com todos os ambientes
const generateId = (): string => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2);
};

export const storageService = {
  savePlan: (plan: LessonPlan): SavedLessonPlan => {
    try {
      const history = storageService.getHistory();

      const newSavedPlan: SavedLessonPlan = {
        ...plan,
        id: generateId(),
        createdAt: new Date().toISOString(),
      };

      // Adiciona no início da lista (mais recente primeiro)
      const updatedHistory = [newSavedPlan, ...history];

      // Tenta salvar no localStorage
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedHistory));

      return newSavedPlan;
    } catch (e) {
      console.error("Erro ao salvar plano no histórico:", e);
      // Retorna o plano mesmo se falhar o save, para não quebrar a UI
      return {
        ...plan,
        id: generateId(),
        createdAt: new Date().toISOString()
      };
    }
  },

  getHistory: (): SavedLessonPlan[] => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (!stored) return [];

      const parsed = JSON.parse(stored);

      // Se não for array, considera corrompido e reseta
      if (!Array.isArray(parsed)) {
        console.warn("Histórico corrompido, resetando...");
        localStorage.removeItem(STORAGE_KEY);
        return [];
      }

      return parsed;
    } catch (e) {
      console.error("Erro ao recuperar histórico:", e);
      return [];
    }
  },

  deletePlan: (id: string): SavedLessonPlan[] => {
    try {
      const history = storageService.getHistory();
      const updatedHistory = history.filter(plan => plan.id !== id);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedHistory));
      return updatedHistory;
    } catch (e) {
      console.error("Erro ao excluir do histórico:", e);
      return [];
    }
  }
};

