import { LessonPlan } from "../types";

const AVAILABLE_SKILLS = `
BANCO DE HABILIDADES ESTRUTURANTES (BNCC):
1. EM13LGG204.c.16 - Negociar interesses comuns.
2. EM13LP08.s.6 - Sintaxe do português.
