export const storageService = {
  // Inicialização
  init: () => {
    if (!localStorage.getItem(PLAN_STORAGE_KEY)) {
      const plans = INITIAL_PLANS.map(p => ({
        ...p,
        id: generateId(),
        context: "Exemplo da comunidade",
        learningObjectives: ["Identificar elementos chave", "Analisar criticamente"],
        skills: ["EM13LP01.c.17"],
        development: { what: "Atividade prática", how: "Em grupos de 4" },
        inclusionStrategies: "Uso de material visual e auditivo",
        learningEvidence: "Produção final",
        assessmentInstruments: "Rubrica",
        ods: ["Educação de Qualidade"],
        socioemotionalSkills: ["Colaboração"]
      })) as SavedLessonPlan[];
      localStorage.setItem(PLAN_STORAGE_KEY, JSON.stringify(plans));
    }
    if (!localStorage.getItem(FEEDBACK_STORAGE_KEY)) {
      localStorage.setItem(FEEDBACK_STORAGE_KEY, JSON.stringify(INITIAL_FEEDBACKS));
    }
  },

  // Planos Comunitários
  savePlan: (plan: LessonPlan): SavedLessonPlan => {
    const history = storageService.getHistory();
    const newSavedPlan: SavedLessonPlan = {
      ...plan,
      id: generateId(),
      createdAt: new Date().toISOString(),
    };
    const updatedHistory = [newSavedPlan, ...history];
    localStorage.setItem(PLAN_STORAGE_KEY, JSON.stringify(updatedHistory));
    return newSavedPlan;
  },

  getHistory: (): SavedLessonPlan[] => {
    try {
      const stored = localStorage.getItem(PLAN_STORAGE_KEY);
      return stored ? JSON.parse(stored) : [];
    } catch (e) {
      return [];
    }
  },

  deletePlan: (id: string): SavedLessonPlan[] => {
    const history = storageService.getHistory();
    const updatedHistory = history.filter(plan => plan.id !== id);
    localStorage.setItem(PLAN_STORAGE_KEY, JSON.stringify(updatedHistory));
    return updatedHistory;
  },

  // Feedbacks Públicos
  saveFeedback: (type: 'sugestao' | 'elogio' | 'erro', name: string, message: string): Feedback => {
    const feedbacks = storageService.getFeedbacks();
    const newFeedback: Feedback = {
      id: generateId(),
      type,
      name,
      message,
      createdAt: new Date().toISOString()
    };
    const updated = [newFeedback, ...feedbacks];
    localStorage.setItem(FEEDBACK_STORAGE_KEY, JSON.stringify(updated));
    return newFeedback;
  },

  getFeedbacks: (): Feedback[] => {
    try {
      const stored = localStorage.getItem(FEEDBACK_STORAGE_KEY);
      return stored ? JSON.parse(stored) : [];
    } catch (e) {
      return [];
    }
  }
};

import React, { useState, useCallback, useEffect } from 'react';
import { generateLessonPlan } from './services/geminiService';
import { storageService } from './services/storageService';
import { LessonPlan, AppState, SavedLessonPlan } from './types';
import Header from './components/Header';
import Footer from './components/Footer';
import PlanResult from './components/PlanResult';
import HistoryDrawer from './components/HistoryDrawer';
import FeedbackWidget from './components/FeedbackWidget';
import { BookOpen, Send, Loader2, ClipboardList, AlertCircle, User, XCircle, BrainCircuit, Users } from 'lucide-react';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [teacherName, setTeacherName] = useState('');

  const [state, setState] = useState<AppState>({
    isGenerating: false,
    plan: null,
    error: null,
    showHistory: false
  });
  const [history, setHistory] = useState<SavedLessonPlan[]>([]);

  useEffect(() => {
    // Inicializa o banco com dados de exemplo se estiver vazio
    storageService.init();
    setHistory(storageService.getHistory());
  }, []);

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();

    if (!teacherName.trim()) {
      setState(prev => ({ ...prev, error: "Por favor, insira seu nome antes de gerar o plano." }));
      return;
    }
    if (!inputText.trim()) {
      setState(prev => ({ ...prev, error: "O detalhamento do plano não pode estar vazio." }));
      return;
    }

    setState(prev => ({ ...prev, isGenerating: true, error: null }));

    try {
      const recentMethods = history.slice(0, 5).map(p => `${p.content}: ${p.methodology}`);
      const generatedPlan = await generateLessonPlan(inputText, recentMethods);
      generatedPlan.teacherName = teacherName;

      storageService.savePlan(generatedPlan);
      const updatedHistory = storageService.getHistory();
      setHistory(updatedHistory);

      setState({
        isGenerating: false,
        plan: generatedPlan,
        error: null,
        showHistory: false
      });
    } catch (err: any) {
      console.error("Erro na submissão:", err);
      setState(prev => ({
        ...prev,
        isGenerating: false,
        error: err.message || "Não foi possível gerar o plano agora. Tente novamente em alguns instantes."
      }));
    }
  }, [inputText, teacherName, history]);

  const handleReset = () => {
    setState({ isGenerating: false, plan: null, error: null, showHistory: false });
    setInputText('');
  };

  const handleSelectHistoryPlan = (savedPlan: SavedLessonPlan) => {
    setState(prev => ({ ...prev, plan: savedPlan, showHistory: false, error: null }));
    setTeacherName(savedPlan.teacherName);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm('Excluir este plano do repositório?')) {
      const updated = storageService.deletePlan(id);
      setHistory(updated);
    }
  };

  return (
    <div className="min-h-screen flex flex-col text-slate-800 relative bg-slate-50">
      <Header onOpenHistory={() => setState(prev => ({ ...prev, showHistory: true }))} />

      <HistoryDrawer 
        isOpen={state.showHistory}
        onClose={() => setState(prev => ({ ...prev, showHistory: false }))}
        history={history}
        onSelectPlan={handleSelectHistoryPlan}
        onDeletePlan={handleDeletePlan}
      />

      <FeedbackWidget />

      <main className="flex-grow container mx-auto px-4 py-8 max-w-5xl">
        {!state.plan ? (
          <div className="space-y-10 animate-in fade-in duration-500">

            {state.error && (
              <div className="bg-red-50 border-2 border-red-200 rounded-xl p-5 flex items-start space-x-3 text-red-800 shadow-sm">
                <AlertCircle className="w-6 h-6 shrink-0 text-red-600 mt-1" />
                <div className="flex-grow">
                  <p className="text-sm font-black uppercase tracking-tight mb-1">Atenção Professor:</p>
                  <p className="text-sm leading-relaxed">{state.error}</p>
                </div>
                <button 
                  onClick={() => setState(p => ({...p, error: null}))}
                  className="p-1 hover:bg-red-100 rounded-lg transition-colors"
                >
                  <XCircle className="w-5 h-5" />
                </button>
              </div>
            )}

